"use client";

import React, { useState } from "react";

export default function Key({ letter, status = "idle", onPress, disabled = false }) {
  const [hover, setHover] = useState(false);

  const baseColor = (() => {
    if (status === "success") return "#4caf50"; // green
    if (status === "fail") return "#f44336"; // red
    if (status === "disabled") return "#ddd"; // gray
    return "#fff"; // default
  })();

  // helper: compute contrasting text color (black or white) for readability
  function hexToRgb(hex) {
    const h = hex.replace('#', '');
    const bigint = parseInt(h.length === 3 ? h.split('').map(c=>c+c).join('') : h, 16);
    return {
      r: (bigint >> 16) & 255,
      g: (bigint >> 8) & 255,
      b: bigint & 255,
    };
  }

  function getContrastingTextColor(hex) {
    try {
      const { r, g, b } = hexToRgb(hex);
      // relative luminance
      const [R, G, B] = [r, g, b].map((c) => {
        const cs = c / 255;
        return cs <= 0.03928 ? cs / 12.92 : Math.pow((cs + 0.055) / 1.055, 2.4);
      });
      const lum = 0.2126 * R + 0.7152 * G + 0.0722 * B;
      // if luminance is dark, use white text
      return lum < 0.5 ? '#fff' : '#000';
    } catch (e) {
      return '#000';
    }
  }

  const textColor = getContrastingTextColor(baseColor);

  const hoverModifier = hover && status === "idle" ? "rgba(0,0,0,0.06)" : "transparent";

  const style = {
    minWidth: 36,
    height: 36,
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    border: "1px solid #ccc",
    borderRadius: 6,
    fontSize: 14,
    cursor: disabled || status === "disabled" ? "not-allowed" : "pointer",
    background: baseColor,
    color: textColor,
    boxShadow: hover ? "0 2px 6px rgba(0,0,0,0.08)" : "none",
    transition: "background 120ms, box-shadow 120ms, color 120ms",
    position: "relative",
  };

  return (
    <button
      aria-label={`key-${letter}`}
      style={style}
      onClick={() => !disabled && status !== "disabled" && onPress && onPress(letter)}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      disabled={disabled || status === "disabled"}
    >
      {letter}
      {hover && hoverModifier !== "transparent" && (
        <span style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: 0,
          bottom: 0,
          background: hoverModifier,
          borderRadius: 6,
          pointerEvents: "none",
        }} />
      )}
    </button>
  );
}
